import torch
import torch.nn as nn
from torch.utils import cpp_extension

# ------------------------------------------------------------------
# CUDA source implementing a tiled FP16 GEMM (C = A * B)
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

constexpr int TILE_M = 16;   // rows per thread block
constexpr int TILE_N = 16;   // cols per thread block
constexpr int TILE_K = 16;   // reduction tile size

// ------------------------------------------------------------------
// Kernel: each thread block computes a TILE_M x TILE_N output tile.
// Accumulation is done in FP32 for accuracy, final result cast to FP16.
// ------------------------------------------------------------------
__global__ void matmul_kernel(const half* __restrict__ A,
                              const half* __restrict__ B,
                              half* __restrict__ C,
                              int M, int N, int K) {
    // shared memory for tiles of A and B
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    // Global row and column this thread is responsible for
    int row = blockIdx.y * TILE_M + threadIdx.y;   // [0, M)
    int col = blockIdx.x * TILE_N + threadIdx.x;   // [0, N)

    float acc = 0.0f;

    // Loop over K dimension in tiles
    for (int t = 0; t < (K + TILE_K - 1) / TILE_K; ++t) {
        // Load A tile (with bounds checking)
        int aRow = row;
        int aCol = t * TILE_K + threadIdx.x;
        As[threadIdx.y][threadIdx.x] = (aRow < M && aCol < K)
                                      ? A[aRow * K + aCol]
                                      : __float2half(0.0f);

        // Load B tile (with bounds checking)
        int bRow = t * TILE_K + threadIdx.y;
        int bCol = col;
        Bs[threadIdx.y][threadIdx.x] = (bRow < K && bCol < N)
                                      ? B[bRow * N + bCol]
                                      : __float2half(0.0f);

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }
        __syncthreads();
    }

    // Write result back to C (if inside bounds)
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// Wrapper called from Python
// ------------------------------------------------------------------
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Only half (fp16) tensors are supported");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Input tensors must be CUDA tensors");

    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t N = B.size(1);
    TORCH_CHECK(B.size(0) == K, "Incompatible matrix dimensions");

    auto C = torch::empty({M, N}, A.options());

    dim3 block(TILE_N, TILE_M);                     // 16 x 16 = 256 threads
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M);

    AT_DISPATCH_HALF_TYPES(A.scalar_type(), "matmul_cuda", [&] {
        matmul_kernel<<<grid, block, 0,
                        at::cuda::getCurrentCUDAStream()>>>(
            A.data_ptr<half>(),
            B.data_ptr<half>(),
            C.data_ptr<half>(),
            static_cast<int>(M),
            static_cast<int>(N),
            static_cast<int>(K));
    });

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
    return C;
}

// ------------------------------------------------------------------
// PyBind registration
// ------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_cuda", &matmul_cuda, "FP16 GEMM (CUDA)");
}
'''

# ------------------------------------------------------------------
# Build the extension in‑line
# ------------------------------------------------------------------
matmul_ext = cpp_extension.load_inline(
    name="matmul_ext",
    cpp_sources=[],
    cuda_sources=[cuda_source],
    functions=["matmul_cuda"],
    verbose=False,
)

# ------------------------------------------------------------------
# Python wrapper calling the compiled kernel
# ------------------------------------------------------------------
def matmul_fp16(A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
    return matmul_ext.matmul_cuda(A, B)

# ------------------------------------------------------------------
# Model that mimics the reference implementation but uses the custom kernel
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_fp16(A, B)

# ------------------------------------------------------------------
# Helper to generate test inputs (identical to the reference)
# ------------------------------------------------------------------
def get_inputs():
    M, N = 256, 256
    K = 131072 * 4
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(K, N, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special initialization required
